import re

def parse(lines):
    rec = {}
    used = []
    skip = []
    last = None
    row = re.compile(r'^\|\s*(?P<key>.*?)\s*\|\s?(?P<value>.*?)\s*\|\s*$')
    rule = re.compile(r'^\+[-+=]+\+$')
    for i, ln in enumerate(lines):
        s = ln.strip()
        if not s:
            continue
        if s.startswith('$') or rule.match(s):
            skip.append(i)
            continue
        m = row.match(s)
        if not m:
            continue
        k = m.group('key')
        v = m.group('value').strip()
        if k == 'Field' and v == 'Value':
            skip.append(i)
            continue
        if k == '':
            if last is not None:
                if v:
                    rec[last] = (rec[last] + ' ' + v).strip()
                used.append(i)
            continue
        rec[k] = v
        last = k
        used.append(i)
    blocks = []
    if rec:
        blocks.append({'name': 'hypervisor', 'kind': 'kv', 'lines': used, 'records': [rec]})
    return {'blocks': blocks, 'skip': skip}
